using static StrataLint.Scribe.DefinitionDsl;

namespace StrataLint.Scribe.Blueprint.D5.S3.Weil.ZetaBridge;

internal sealed class ActualThreeNodeFiniteLimitsDocument : IScribeDocumentDefinition
{
    public DocumentDefinition Create() => DocumentDefinition.Create(ScribeNode.Create(
        "Actual three-node FiniteLimits", H("Actual three-node FiniteLimits"),
        Blocks(
            Paragraph(Text("For fixed signed integer n, r=n/N tends to zero. Continuity through the discriminant gives rhoPlus->6h, rhoMinus->0 and O->4a^2 when h>0. The positive limit 6h justifies division by rhoPlus on one eventual set.")),
            Paragraph(Text("The exact determinant identity gives N^2 rhoMinus -> n^2 a^2(g^2+4mu)/(9h). If a!=0, rhoMinus eventually lies below O; sorting yields the first two limits max(6h,4a^2) and min(6h,4a^2), preserving the top tie.")),
            Paragraph(Text("When a=0 and n!=0, N^4 rhoMinus ->16h n^4/135 and N^2 O=4h n^2/3 for N>0. Exact exterior ordering supplies the three sorted limits with powers 0,2,4.")),
            Paragraph(Text("The sequences remain total at N=0. Algebraic cancellations use N>=1 eventually; no sign condition n>0, eigenvector condition, or artificial separation between two vanishing roots is imposed.")),
            Describe.Lean(DescribeId.Create("roots-at-zero"),
                DeclarationHandle.Create("D5/S3/Weil/ZetaBridge/ActualThreeNodeFiniteLimits.roots_at_zero"),
                H("roots at zero"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(),
                Blocks(Paragraph(Text("lemma roots_at_zero (g mu a : ℝ) (hh : 0 ≤ g ^ 2 + mu) :\n    rhoPlus g mu a 0 = 6 * (g ^ 2 + mu) ∧ rhoMinus g mu a 0 = 0"))), DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("root-limits"),
                DeclarationHandle.Create("D5/S3/Weil/ZetaBridge/ActualThreeNodeFiniteLimits.root_limits"),
                H("root limits"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(),
                Blocks(Paragraph(Text("lemma root_limits (g mu a : ℝ) (n : ℤ) (hh : 0 < g ^ 2 + mu) :\n    Tendsto (fun N : ℕ => rhoPlus g mu a ((n : ℝ) / N)) atTop (𝓝 (6 * (g ^ 2 + mu))) ∧\n    Tendsto (fun N : ℕ => rhoMinus g mu a ((n : ℝ) / N)) atTop (𝓝 0) ∧\n    Tendsto (fun N : ℕ => O g mu a ((n : ℝ) / N)) atTop (𝓝 (4 * a ^ 2))"))), DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("det-reduced"),
                DeclarationHandle.Create("D5/S3/Weil/ZetaBridge/ActualThreeNodeFiniteLimits.detReduced"),
                H("detReduced"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(),
                Blocks(Paragraph(Text("def detReduced (g mu a r : ℝ) : ℝ :=\n  2 * a ^ 2 * (g ^ 2 + 4 * mu) / 3 +\n  (4 * g * a * (g ^ 2 + mu) / 3) * r +\n  (2 * a ^ 2 * g ^ 2 - 16 * a ^ 2 * (g ^ 2 + mu) / 9 +\n    32 * (g ^ 2 + mu) ^ 2 / 45) * r ^ 2 +\n  (4 * g * a * (g ^ 2 + mu) / 15) * r ^ 3 +\n  (a ^ 2 * (g ^ 2 + 16 * mu) / 30) * r ^ 4"))), DescribeRole.Definition),
            Describe.Lean(DescribeId.Create("determinant-factored"),
                DeclarationHandle.Create("D5/S3/Weil/ZetaBridge/ActualThreeNodeFiniteLimits.determinant_factored"),
                H("determinant factored"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(),
                Blocks(Paragraph(Text("lemma determinant_factored (g mu a r : ℝ) :\n    evenDet g mu a r = r ^ 2 * detReduced g mu a r"))), DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("scaled-det-two"),
                DeclarationHandle.Create("D5/S3/Weil/ZetaBridge/ActualThreeNodeFiniteLimits.scaled_det_two"),
                H("scaled det two"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(),
                Blocks(Paragraph(Text("lemma scaled_det_two (g mu a : ℝ) (n : ℤ) (N : ℕ) (hN : N ≠ 0) :\n    (N : ℝ) ^ 2 * evenDet g mu a ((n : ℝ) / N) =\n      (n : ℝ) ^ 2 * detReduced g mu a ((n : ℝ) / N)"))), DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("scaled-det-four-zero"),
                DeclarationHandle.Create("D5/S3/Weil/ZetaBridge/ActualThreeNodeFiniteLimits.scaled_det_four_zero"),
                H("scaled det four zero"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(),
                Blocks(Paragraph(Text("lemma scaled_det_four_zero (g mu : ℝ) (n : ℤ) (N : ℕ) (hN : N ≠ 0) :\n    (N : ℝ) ^ 4 * evenDet g mu 0 ((n : ℝ) / N) =\n      32 * (g ^ 2 + mu) ^ 2 * (n : ℝ) ^ 4 / 45"))), DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("scaled-small-root-limit"),
                DeclarationHandle.Create("D5/S3/Weil/ZetaBridge/ActualThreeNodeFiniteLimits.scaled_small_root_limit"),
                H("scaled small root limit"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(),
                Blocks(Paragraph(Text("lemma scaled_small_root_limit (g mu a : ℝ) (n : ℤ) (hh : 0 < g ^ 2 + mu) :\n    Tendsto (fun N : ℕ => (N : ℝ) ^ 2 * rhoMinus g mu a ((n : ℝ) / N)) atTop\n      (𝓝 ((n : ℝ) ^ 2 * a ^ 2 * (g ^ 2 + 4 * mu) / (9 * (g ^ 2 + mu))))"))), DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("scaled-small-root-limit-zero"),
                DeclarationHandle.Create("D5/S3/Weil/ZetaBridge/ActualThreeNodeFiniteLimits.scaled_small_root_limit_zero"),
                H("scaled small root limit zero"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(),
                Blocks(Paragraph(Text("lemma scaled_small_root_limit_zero (g mu : ℝ) (n : ℤ) (hh : 0 < g ^ 2 + mu) :\n    Tendsto (fun N : ℕ => (N : ℝ) ^ 4 * rhoMinus g mu 0 ((n : ℝ) / N)) atTop\n      (𝓝 (16 * (g ^ 2 + mu) * (n : ℝ) ^ 4 / 135))"))), DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("nonzero-eventually-sorted"),
                DeclarationHandle.Create("D5/S3/Weil/ZetaBridge/ActualThreeNodeFiniteLimits.nonzero_eventually_sorted"),
                H("nonzero eventually sorted"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(),
                Blocks(Paragraph(Text("lemma nonzero_eventually_sorted (g mu a : ℝ) (n : ℤ) (hh : 0 < g ^ 2 + mu) (ha : a ≠ 0) :\n    ∀ᶠ N : ℕ in atTop,\n      finiteEigen g mu a ((n : ℝ) / N) =\n        ![max (rhoPlus g mu a ((n : ℝ) / N)) (O g mu a ((n : ℝ) / N)),\n          min (rhoPlus g mu a ((n : ℝ) / N)) (O g mu a ((n : ℝ) / N)),\n          rhoMinus g mu a ((n : ℝ) / N)]"))), DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("finite-nonzero-limits"),
                DeclarationHandle.Create("D5/S3/Weil/ZetaBridge/ActualThreeNodeFiniteLimits.finite_nonzero_limits"),
                H("finite nonzero limits"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(),
                Blocks(Paragraph(Text("theorem finite_nonzero_limits (g mu a : ℝ) (n : ℤ) (hh : 0 < g ^ 2 + mu) (ha : a ≠ 0) :\n    Tendsto (fun N : ℕ => finiteEigen g mu a ((n : ℝ) / N) 0) atTop\n      (𝓝 (max (6 * (g ^ 2 + mu)) (4 * a ^ 2))) ∧\n    Tendsto (fun N : ℕ => finiteEigen g mu a ((n : ℝ) / N) 1) atTop\n      (𝓝 (min (6 * (g ^ 2 + mu)) (4 * a ^ 2))) ∧\n    Tendsto (fun N : ℕ => (N : ℝ) ^ 2 * finiteEigen g mu a ((n : ℝ) / N) 2) atTop\n      (𝓝 ((n : ℝ) ^ 2 * a ^ 2 * (g ^ 2 + 4 * mu) / (9 * (g ^ 2 + mu))))"))), DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("exterior-eventually"),
                DeclarationHandle.Create("D5/S3/Weil/ZetaBridge/ActualThreeNodeFiniteLimits.exterior_eventually"),
                H("exterior eventually"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(),
                Blocks(Paragraph(Text("lemma exterior_eventually (n : ℤ) :\n    ∀ᶠ N : ℕ in atTop, 1 ≤ N ∧ |(n : ℝ)| < (N : ℝ)"))), DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("zero-eventually-sorted"),
                DeclarationHandle.Create("D5/S3/Weil/ZetaBridge/ActualThreeNodeFiniteLimits.zero_eventually_sorted"),
                H("zero eventually sorted"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(),
                Blocks(Paragraph(Text("lemma zero_eventually_sorted (g mu : ℝ) {n : ℤ} (hn : n ≠ 0) (hh : 0 < g ^ 2 + mu) :\n    ∀ᶠ N : ℕ in atTop,\n      finiteEigen g mu 0 ((n : ℝ) / N) =\n        ![rhoPlus g mu 0 ((n : ℝ) / N), O g mu 0 ((n : ℝ) / N),\n          rhoMinus g mu 0 ((n : ℝ) / N)]"))), DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("zero-scaled-odd"),
                DeclarationHandle.Create("D5/S3/Weil/ZetaBridge/ActualThreeNodeFiniteLimits.zero_scaled_odd"),
                H("zero scaled odd"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(),
                Blocks(Paragraph(Text("lemma zero_scaled_odd (g mu : ℝ) (n : ℤ) (N : ℕ) (hN : N ≠ 0) :\n    (N : ℝ) ^ 2 * O g mu 0 ((n : ℝ) / N) = 4 * (g ^ 2 + mu) * (n : ℝ) ^ 2 / 3"))), DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("finite-zero-limits"),
                DeclarationHandle.Create("D5/S3/Weil/ZetaBridge/ActualThreeNodeFiniteLimits.finite_zero_limits"),
                H("finite zero limits"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(),
                Blocks(Paragraph(Text("theorem finite_zero_limits (g mu : ℝ) {n : ℤ} (hn : n ≠ 0) (hh : 0 < g ^ 2 + mu) :\n    Tendsto (fun N : ℕ => finiteEigen g mu 0 ((n : ℝ) / N) 0) atTop\n      (𝓝 (6 * (g ^ 2 + mu))) ∧\n    Tendsto (fun N : ℕ => (N : ℝ) ^ 2 * finiteEigen g mu 0 ((n : ℝ) / N) 1) atTop\n      (𝓝 (4 * (g ^ 2 + mu) * (n : ℝ) ^ 2 / 3)) ∧\n    Tendsto (fun N : ℕ => (N : ℝ) ^ 4 * finiteEigen g mu 0 ((n : ℝ) / N) 2) atTop\n      (𝓝 (16 * (g ^ 2 + mu) * (n : ℝ) ^ 4 / 135))"))), DescribeRole.Theorem))));
}
